Table: empty.
1. A -> B  (src aa:aa, dst bb:bb) arrives on port 1
   learn   aa:aa = port 1
   lookup  bb:bb -> miss, unknown unicast
   action  flood out ports 2 and 3 (C sees it, ignores it)
2. B -> A  (src bb:bb, dst aa:aa) arrives on port 2
   learn   bb:bb = port 2
   lookup  aa:aa -> hit, port 1
   action  forward out port 1 only
3. A -> B again
   refresh aa:aa
   lookup  bb:bb -> hit, port 2
   action  forward out port 2 only; C no longer sees it
4. B plugs into port 5 (moved), sends anything
   learn   bb:bb = port 5   (entry moves, old port 2 is forgotten)

#include <stdint.h>
#include <string.h>
#include <time.h>

#define FDB_SIZE 8192
#define AGING_SEC 300
#define FLOOD (-1)

struct fdb_entry {
    uint8_t  mac[6];
    uint16_t vlan;
    int      port;
    time_t   last_seen;
    int      valid;
};
static struct fdb_entry fdb[FDB_SIZE];

static unsigned hash(const uint8_t *mac, uint16_t vlan) {
    unsigned h = vlan;
    for (int i = 0; i < 6; i++) h = h * 31 + mac[i];
    return h % FDB_SIZE;
}

void learn(const uint8_t *src, uint16_t vlan, int port, time_t now) {
    if (src[0] & 1) return;              /* never learn group addresses */
    struct fdb_entry *e = &fdb[hash(src, vlan)];
    memcpy(e->mac, src, 6);              /* collision simply overwrites */
    e->vlan = vlan; e->port = port;
    e->last_seen = now; e->valid = 1;
}

int lookup(const uint8_t *dst, uint16_t vlan, time_t now) {
    struct fdb_entry *e = &fdb[hash(dst, vlan)];
    if (dst[0] & 1) return FLOOD;        /* broadcast or multicast */
    if (e->valid && e->vlan == vlan && memcmp(e->mac, dst, 6) == 0 &&
        now - e->last_seen < AGING_SEC)
        return e->port;
    return FLOOD;                        /* unknown unicast */
}
